import io.github.diodeme.ji.agent.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.session.memory.*;
import io.github.diodeme.ji.testkit.*;
import java.util.*;
import java.security.*;
var provider = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore()).build();
var sessions = new SessionApplicationService(runtime);
var store = new MemoryHostStore();
var prompts = new PromptApplicationService(sessions, store);
var session = sessions.create(new ModelRef("faux", "faux-1"), ".");
var sessionId = session.id();
session.close();
try { prompts.prompt(sessionId, "cmd-1", "hello"); } catch (Exception failure) { System.out.println("START_FAILED=" + failure.getClass().getSimpleName() + ":" + failure.getMessage()); }
var payloadHash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest("hello".getBytes(java.nio.charset.StandardCharsets.UTF_8)));
System.out.println("JOURNAL_PRESENT_AFTER_FAILURE=" + store.command(sessionId, "cmd-1", payloadHash).isPresent());
sessions.close();
/exit
'@
