import com.sun.net.httpserver.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.provider.openai.*;
import java.net.*;
import java.nio.charset.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.Flow;
var release = new CountDownLatch(1);
var server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
server.createContext("/v1/chat/completions", exchange -> { try { exchange.getRequestBody().readAllBytes(); exchange.getResponseHeaders().set("Content-Type", "text/event-stream"); exchange.sendResponseHeaders(200, 0); exchange.getResponseBody().write("data: {\"id\":\"response-1\",\"choices\":[{\"delta\":{}}]}\n".getBytes(StandardCharsets.UTF_8)); exchange.getResponseBody().flush(); release.await(5, TimeUnit.SECONDS); exchange.getResponseBody().write("data: [DONE]\n".getBytes(StandardCharsets.UTF_8)); exchange.close(); } catch (Exception ignored) { exchange.close(); } });
server.start();
var cancellation = new CancellationSource();
var request = new ModelRequest("session-1", new ModelRef("openai", "model"), "", List.of(new Message("message-1", Message.Role.USER, List.of(new Content.Text("hello")), Instant.EPOCH)), List.of(), Map.of(), cancellation.token());
var events = new CopyOnWriteArrayList<ModelStreamEvent>();
var started = new CountDownLatch(1);
var done = new CountDownLatch(1);
var provider = OpenAiProvider.builder().baseUrl("http://127.0.0.1:" + server.getAddress().getPort()).build();
provider.stream(request).subscribe(new Flow.Subscriber<ModelStreamEvent>() { public void onSubscribe(Flow.Subscription s){s.request(Long.MAX_VALUE);} public void onNext(ModelStreamEvent e){events.add(e); if(e instanceof ModelStreamEvent.Started) started.countDown();} public void onError(Throwable t){done.countDown();} public void onComplete(){done.countDown();} });
System.out.println("STARTED=" + started.await(3, TimeUnit.SECONDS));
cancellation.cancel();
System.out.println("ABORT_TERMINATED_WITHIN_1S=" + done.await(1, TimeUnit.SECONDS));
release.countDown();
done.await(3, TimeUnit.SECONDS);
System.out.println("FINAL_EVENTS=" + events);
provider.close();
server.stop(0);
/exit
'@
